<?php get_header(); if(have_posts()): while(have_posts()): the_post(); ?><section class="glo-page-hero"><div class="glo-container"><p class="glo-eyebrow"><?php echo esc_html(get_the_title()); ?></p><h1><?php the_title(); ?></h1><?php if(has_excerpt()): ?><p class="glo-lead"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?></div></section><section class="glo-content"><div class="glo-container glo-prose"><?php the_content(); ?></div></section><?php endwhile; endif; get_footer(); ?>
